class Solution {
  public long minNumberOfSeconds(int mountainHeight, int[] workerTimes) {
    long lo = 1, hi = 0;
    for (int t : workerTimes)
      hi = Math.max(hi, (long) t * mountainHeight * (mountainHeight + 1L) / 2);
    while (lo < hi) {
      long mid = (lo + hi) >>> 1;
      if (reduced(workerTimes, mid) >= mountainHeight) hi = mid;
      else lo = mid + 1;
    }
    return lo;
  }

  // total height removed if every worker may work for `time` seconds
  private long reduced(int[] workerTimes, long time) {
    long total = 0;
    for (int t : workerTimes) {
      long q = time / t; // largest x with x * (x + 1) / 2 <= q
      long x = (long) ((Math.sqrt(1 + 8.0 * q) - 1) / 2);
      while ((x + 1) * (x + 2) / 2 <= q) x++;
      while (x > 0 && x * (x + 1) / 2 > q) x--;
      total += x;
    }
    return total;
  }
}
